const TRANSIENT_RETRY_DELAYS_MS = [15_000, 45_000, 90_000, 180_000];

type DifficultyBucket = "easy" | "medium" | "hard";

interface BenchmarkCase {
  case_id: string;
  category: string;
  difficulty_bucket: DifficultyBucket;
  messages: readonly { role: string; content: string }[];
  expected_response: string;
  grading_criteria: string;
  answer_format?: { kind?: string; language?: string; instruction?: string };
  taxonomy_tags?: { roleId?: string; taskType?: string; domain?: string };
  grading_method?: string;
  source_benchmark?: string;
  test_code?: string;
  entry_point?: string;
  canonical_solution?: string;
}

interface BenchmarkSuite {
  suite_id: string;
  family: string;
  description: string;
  cases: readonly BenchmarkCase[];
}

interface ModelCallResult {
  text: string;
  latencyMs: number;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  modelUsed: string;
}

interface SubjectRun {
  modelId: string;
  modelLabel: string;
  actualText: string;
  extractedAnswer?: string;
  extractedCode?: string;
  latencyMs: number;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  exec?: ExecResult;
  binaryCorrect?: boolean;
}

interface ExecResult {
  passed: number;
  failed: number;
  output: string;
  errors: string[];
