function formatBenchmarkRawResponse(result: BenchmarkChatCompletionsExecutionResult): string {
  const chunks: string[] = [];

  const content = readBenchmarkContentText(result);

  if (content) {
    chunks.push(content);
  }

  if (result.toolCalls?.length) {
    for (const toolCall of result.toolCalls) {
