  prior: readonly BenchmarkToolCall[],
  latest: readonly BenchmarkToolCall[] | undefined,
): readonly BenchmarkToolCall[] {
  if (!latest?.length) {
    return prior;
  }
  return [...prior, ...latest];
}

function mergeStructuredToolNames(
  prior: readonly string[],
