function tryParseJson(raw: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(raw.trim());
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed;
    }
  } catch {}
  const fenced = extractFence(raw, "json");
  if (!fenced) return null;
  try {
    const parsed = JSON.parse(fenced);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed;
    }
  } catch {}
  return null;
}

function extractMmluAnswer(raw: string): string {
  const json = tryParseJson(raw);
  const fromJson = typeof json?.answer === "string" ? json.answer : "";
  const text = (fromJson || raw).trim().toUpperCase();
  const match = text.match(/\b([A-J])\b/);
  return match?.[1] ?? "";
}

function extractPython(raw: string): string {
  return extractFence(raw, "python") ?? extractFence(raw) ?? "";
}

function truncateForJudge(text: string, maxChars = 4000): string {
  const normalized = text.trim();
  if (normalized.length <= maxChars) return normalized;
  return `${normalized.slice(0, maxChars)}\n...[truncated ${normalized.length - maxChars} chars]`;
}

async function callModel(messages: readonly { role: string; content: string }[], model: string): Promise<ModelCallResult> {
  let lastError: Error | null = null;
  for (let attempt = 0; attempt <= TRANSIENT_RETRY_DELAYS_MS.length; attempt += 1) {
    try {
      const started = Date.now();
      const res = await fetch(ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model, messages, temperature: 0 }),
        signal: AbortSignal.timeout(300_000),
      });
      if (res.ok) {
        const json = await res.json() as {
          model?: string;
          choices?: Array<{ message?: { content?: string } }>;
          usage?: { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number };
        };
        return {
          text: json.choices?.[0]?.message?.content ?? "",
          latencyMs: Date.now() - started,
          promptTokens: json.usage?.prompt_tokens ?? 0,
          completionTokens: json.usage?.completion_tokens ?? 0,
          totalTokens: json.usage?.total_tokens ?? 0,
          modelUsed: json.model ?? model,
        };
      }
      const text = await res.text().catch(() => "unknown");
      lastError = new Error(`HTTP ${res.status}: ${text.slice(0, 400)}`);
      const transient =
        res.status === 503 &&
        /temporarily unavailable|recent execution failures|no_eligible_target/i.test(text);
      if (!transient || attempt === TRANSIENT_RETRY_DELAYS_MS.length) {
        throw lastError;
      }
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));
      if (attempt === TRANSIENT_RETRY_DELAYS_MS.length) {
        throw lastError;
      }
    }
    await sleep(TRANSIENT_RETRY_DELAYS_MS[attempt]);
  }
  throw lastError ?? new Error("unknown model call failure");
}

