      errors: string[];
      testsRun: number;
    };
    return {
      passed: parsed.passed,
      failed: parsed.failed,
      output: stdout.slice(-2000),
      errors: parsed.errors,
    };
  } catch (error) {
    const output = error instanceof Error ? error.message : String(error);
    return { passed: 0, failed: 1, output: output.slice(-2000), errors: [output.slice(-1000)] };
  } finally {
    try { fss.unlinkSync(file); } catch {}
  }
}

async function judgePairwise(caseItem: BenchmarkCase, modelA: SubjectRun, modelB: SubjectRun): Promise<JudgePairwise> {
  const modelAText = truncateForJudge(modelA.actualText);
  const modelBText = truncateForJudge(modelB.actualText);
  const modelAExec = modelA.exec
    ? `official_test_result: passed=${modelA.exec.passed} failed=${modelA.exec.failed} errors=${truncateForJudge(JSON.stringify(modelA.exec.errors), 1200)}`
    : "";
  const modelBExec = modelB.exec
    ? `official_test_result: passed=${modelB.exec.passed} failed=${modelB.exec.failed} errors=${truncateForJudge(JSON.stringify(modelB.exec.errors), 1200)}`
    : "";
  const prompt = [
    "You are grading two benchmark responses side by side.",
    "Use the benchmark question, expected answer, grading criteria, and any provided test results.",
    "Score each response from 0.0 to 1.0, choose a winner, and explain briefly but concretely.",
    "",
    "Output ONLY one JSON object on one line with this shape:",
    '{"winner":"model_a|model_b|tie","model_a_score":0.0,"model_b_score":0.0,"rationale":"..."}',
    "",
    "Rules:",
    "- Use the expected answer when it is authoritative.",
    "- For code tasks, use the official test results as the primary signal.",
    "- Do not reward verbosity.",
    "- If both are materially equivalent, return tie.",
    "",
    "## QUESTION",
    caseItem.messages.map((m) => `${m.role.toUpperCase()}: ${m.content}`).join("\n\n"),
    "",
    "## EXPECTED ANSWER",
    caseItem.expected_response,
    "",
    "## GRADING CRITERIA",
    caseItem.grading_criteria,
    "",
    "## MODEL A",
    `model_id: ${modelA.modelId}`,
    `raw_output:\n${modelAText}`,
    modelA.extractedAnswer ? `parsed_answer: ${modelA.extractedAnswer}` : "",
    modelAExec,
    "",
    "## MODEL B",
    `model_id: ${modelB.modelId}`,
    `raw_output:\n${modelBText}`,
    modelB.extractedAnswer ? `parsed_answer: ${modelB.extractedAnswer}` : "",
    modelBExec,
  ].filter(Boolean).join("\n");

  await sleep(15_000);
  const judged = await callModel([{ role: "user", content: prompt }], JUDGE_MODEL);
  const parsed = tryParseJson(judged.text);
  if (!parsed) {
    throw new Error(`Judge returned non-JSON: ${judged.text.slice(0, 400)}`);
  }
  const winner = parsed.winner;
  if (winner !== "model_a" && winner !== "model_b" && winner !== "tie") {
    throw new Error(`Invalid judge winner: ${String(winner)}`);
  }
  return {
    winner,
    model_a_score: Number(parsed.model_a_score ?? 0),
    model_b_score: Number(parsed.model_b_score ?? 0),
    rationale: String(parsed.rationale ?? ""),
  };
}

async function runSubject(caseItem: BenchmarkCase, model: typeof SUBJECT_MODELS[number], family: string): Promise<SubjectRun> {
  if (model.id === "chatgpt/gpt-5.4") {
    await sleep(15_000);
  }
  const response = await callModel(caseItem.messages, model.id);
  const subject: SubjectRun = {
    modelId: model.id,
    modelLabel: model.label,
    actualText: response.text,
    latencyMs: response.latencyMs,
    promptTokens: response.promptTokens,
    completionTokens: response.completionTokens,
    totalTokens: response.totalTokens,
  };
  if (family === "mmlu_pro") {
    const answer = extractMmluAnswer(response.text);
    subject.extractedAnswer = answer;
    subject.binaryCorrect = answer === caseItem.expected_response.trim().toUpperCase();
    return subject;
  }
  if (family === "bigcodebench") {
    const code = extractPython(response.text);
    subject.extractedCode = code;
    if (code && caseItem.test_code && caseItem.entry_point) {
      subject.exec = runBigCodeTests(code, caseItem.test_code, caseItem.entry_point, caseItem.case_id, model.label);
    } else {
      subject.exec = { passed: 0, failed: 1, output: "", errors: ["Code extraction failed"] };
    }
    return subject;
  }
  return subject;
}

function summarizeFamily(artifacts: CaseArtifact[]) {
  const aWins = artifacts.filter((x) => x.judge.winner === "model_a").length;
