async function main() {
  const fixtureDir = path.join("C:\\Users\\erikb\\AppData\\Local\\Temp\\rm-pilot-spike", "fixture");
  const outDir = path.join("C:\\Users\\erikb\\AppData\\Local\\Temp\\rm-pilot-spike", "output");
  const familyArgIndex = process.argv.indexOf("--family");
  const requestedFamily = familyArgIndex >= 0 ? process.argv[familyArgIndex + 1] : null;
  const requestedFiles = requestedFamily ? {
    mmlu_pro: ["mmlu-pro-real-suite.json"],
    arena_hard_200: ["arena-hard-real-suite.json"],
    bigcodebench: ["bigcodebench-real-stdlib-suite.json"],
  }[requestedFamily] : null;
  const families = requestedFiles ?? (process.argv.includes("--all") ? [
    "mmlu-pro-real-suite.json",
    "arena-hard-real-suite.json",
    "bigcodebench-real-stdlib-suite.json",
  ] : ["mmlu-pro-real-suite.json"]);
  await fs.mkdir(outDir, { recursive: true });

  const familySummaries: Array<Record<string, unknown>> = [];

  for (const filename of families) {
    const suite = JSON.parse(await fs.readFile(path.join(fixtureDir, filename), "utf8")) as BenchmarkSuite;
    const family = suite.family;
    const outFile = path.join(outDir, `audited-headtohead-${family}.json`);
    let artifacts: CaseArtifact[] = [];
    try {
      const prior = JSON.parse(await fs.readFile(outFile, "utf8")) as { artifacts?: CaseArtifact[] };
      artifacts = prior.artifacts ?? [];
    } catch {}
    const completedCaseIds = new Set(artifacts.map((item) => item.caseId));
    process.stdout.write(`\n=== ${family} :: ${suite.cases.length} cases ===\n`);
    for (const caseItem of suite.cases) {
      if (completedCaseIds.has(caseItem.case_id)) {
        process.stdout.write(`Skipping ${caseItem.case_id} (already completed)\n`);
        continue;
      }
      process.stdout.write(`Running ${caseItem.case_id}\n`);
      const modelA = await runSubject(caseItem, SUBJECT_MODELS[0], family);
      const modelB = await runSubject(caseItem, SUBJECT_MODELS[1], family);
      const judge = await judgePairwise(caseItem, modelA, modelB);
      artifacts.push({
        family,
        suiteId: suite.suite_id,
        caseId: caseItem.case_id,
        category: caseItem.category,
        difficulty: caseItem.difficulty_bucket,
        question: caseItem.messages.map((m) => `${m.role}: ${m.content}`).join("\n\n"),
        expectedResponse: caseItem.expected_response,
        gradingCriteria: caseItem.grading_criteria,
        taxonomy: {
          roleId: caseItem.taxonomy_tags?.roleId ?? "",
          taskType: caseItem.taxonomy_tags?.taskType ?? "",
          domain: caseItem.taxonomy_tags?.domain ?? "",
        },
        modelA,
        modelB,
        judge,
      });
      process.stdout.write(`  winner=${judge.winner} a=${judge.model_a_score.toFixed(2)} b=${judge.model_b_score.toFixed(2)}\n`);
      const runningSummary = summarizeFamily(artifacts);
      await fs.writeFile(
        outFile,
        `${JSON.stringify({ family, suiteId: suite.suite_id, judgeModel: JUDGE_MODEL, artifacts, summary: runningSummary }, null, 2)}\n`,
        "utf8",
      );
    }

    const summary = summarizeFamily(artifacts);
    familySummaries.push({
      family,
      suiteId: suite.suite_id,
      cases: artifacts.length,
      modelA: SUBJECT_MODELS[0].id,
      modelB: SUBJECT_MODELS[1].id,
      judgeModel: JUDGE_MODEL,
      ...summary,
    });

    await fs.writeFile(
      outFile,
      `${JSON.stringify({ family, suiteId: suite.suite_id, judgeModel: JUDGE_MODEL, artifacts, summary }, null, 2)}\n`,
      "utf8",
    );
  }

  await fs.writeFile(
    path.join(outDir, "audited-headtohead-summary.json"),
    `${JSON.stringify({ generatedAt: new Date().toISOString(), familySummaries }, null, 2)}\n`,
    "utf8",
  );
}

main().catch((error) => {
