{"content":"/**
 * Phase 1: Run all subjects through all benchmarks.
 * Saves raw responses to {family}-subjects.json checkpoint files.
 * Judging is done separately in run-phase2-judge.js.
 */
import * as fs from "node:fs/promises";
import * as fss from "node:fs";
import * as path from "node:path";
import { execFileSync } from "node:child_process";

const ROOT = "C:\\Users\\erikb\\AppData\\Local\\Temp\\rm-pilot-spike";
const FIXTURE = path.join(ROOT, "fixture");
const OUTPUT = path.join(ROOT, "output");
const ENDPOINT = "http://127.0.0.1:3456/v1/chat/completions";
const PYTHON = "C:\\Python314\\python.exe";

const SUBJECT_MODELS = [
  { id: "difficulty.remote-only", label: "deepseek_v4_pro" },
  { id: "chatgpt/gpt-5.4", label: "gpt_5_4" },
] as const;

const TRANSIENT_RETRY_DELAYS_MS = [15_000, 45_000, 90_000, 180_000];

/** ── Types ── */

interface ModelCallResult {
  text: string;
  latencyMs: number;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  modelUsed: string;
}

interface ExecResult {
  passed: number;
  failed: number;
  output: string;
  errors: string[];
}

interface SubjectRun {
  modelId: string;
  modelLabel: string;
  actualText: string;
  extractedAnswer?: string;
  extractedCode?: string;
  latencyMs: number;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  exec?: ExecResult;
  binaryCorrect?: boolean;
}

interface CaseSubjects {
  caseId: string;
  subjects: SubjectRun[];
}

interface SuiteSubjects {
  family: string;
  suiteId: string;
  cases: CaseSubjects[];
  generatedAt: string;
}

/** ── Helpers ── */

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function extractFence(raw: string, lang?: string): string | null {
  const regex = /```([a-zA-Z0-9_-]*)\r?\n([\s\S]*?)```/g;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(raw)) !== null) {
    const actualLang = (match[1] ?? "").toLowerCase();
    if (!lang || !actualLang || actualLang === lang.toLowerCase()) {
      return match[2].trim();
    }
  }
  return null;
}

function tryParseJson(raw: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(raw.trim());
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed as Record<string, unknown>;
  } catch {}
  const fenced = extractFence(raw, "json");
  if (!fenced) return null;
  try {
    const parsed = JSON.parse(fenced);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed as Record<string, unknown>;
  } catch {}
  return null;
}

function extractMmluAnswer(raw: string): string {
  const json = tryParseJson(raw);
  const fromJson = typeof json?.answer === "string" ? json.answer : "";
  const text = (fromJson || raw).trim().toUpperCase();
  const match = text.match(/\b([A-J])\b/);
  return match?.[1] ?? "";
}

function extractPython(raw: string): string {
  return extractFence(raw, "python") ?? extractFence(raw) ?? "";
}

async function callModel(
  messages: readonly { role: string; content: string }[],
  model: string,
): Promise<ModelCallResult> {
  for (let attempt = 0; attempt <= TRANSIENT_RETRY_DELAYS_MS.length; attempt += 1) {
    try {
      const started = Date.now();
      const res = await fetch(ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model, messages, temperature: 0 }),
        signal: AbortSignal.timeout(300_000),
      });
      if (res.ok) {
        const json = (await res.json()) as {
          model?: string;
          choices?: Array<{ message?: { content?: string } }>;
          usage?: { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number };
        };
        return {
          text: json.choices?.[0]?.message?.content ?? "",
          latencyMs: Date.now() - started,
          promptTokens: json.usage?.prompt_tokens ?? 0,
          completionTokens: json.usage?.completion_tokens ?? 0,
          totalTokens: json.usage?.total_tokens ?? 0,
          modelUsed: json.model ?? model,
        };
      }
      const text = await res.text().catch(() => "unknown");
      const err = new Error(`HTTP ${res.status}: ${text.slice(0, 400)}`);
      const transient =
        res.status === 503 &&
        /temporarily unavailable|recent execution failures|no_eligible_target/i.test(text);
      if (!transient || attempt === TRANSIENT_RETRY_DELAYS_MS.length) throw err;
    } catch (error) {
      const lastError = error instanceof Error ? error : new Error(String(error));
      if (attempt === TRANSIENT_RETRY_DELAYS_MS.length) throw lastError;
    }
    await sleep(TRANSIENT_RETRY_DELAYS_MS[attempt]);
  }
  throw new Error("unreachable");
}

function sanitizePython(code: string): string {
  return code.replace(/^\s*```python\s*/i, "").replace(/\s*```\s*$/i, "").trim();
}

function runBigCodeTests(
  code: string,
  testCode: string,
  entryPoint: string,
  caseId: string,
  modelLabel: string,
): ExecResult {
  const tmpDir = path.join(ROOT, "tmp");
  fss.mkdirSync(tmpDir, { recursive: true });
  const slug = `${caseId}-${modelLabel}-${Date.now()}`.replace(/[^a-zA-Z0-9_-]/g, "_");
  const file = path.join(tmpDir, `${slug}.py`);
  const harness = [
    sanitizePython(code),
    "",
    testCode,
    "",
    "if __name__ == '__main__':",
    "    import json",
    "    import unittest",
    "    suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestCases)",
    "    result = unittest.TextTestRunner(verbosity=0).run(suite)",
    "    payload = {",
    "        'passed': result.testsRun - len(result.failures) - len(result.errors),",
    "        'failed': len(result.failures) + len(result.errors),",
    "        'errors': [str(x[1])[:500] for x in result.failures + result.errors],",
    "        'testsRun': result.testsRun,",
    "    }",
    "    print('JSON_RESULT=' + json.dumps(payload))",
  ].join("\n");
  fss.writeFileSync(file, harness, "utf8");
  try {
    const stdout = execFileSync(PYTHON, [file], { encoding: "utf8", timeout: 180_000 });
    const marker = stdout
      .split(/\r?\n/)
      .find((line) => line.startsWith("JSON_RESULT="));
    if (!marker) {
      return { passed: 0, failed: 1, output: stdout.slice(-2000), errors: ["Missing JSON_RESULT marker"] };
    }
    const parsed = JSON.parse(marker.slice("JSON_RESULT=".length)) as {
      passed: number;
      failed: number;
      errors: string[];
      testsRun: number;
    };
    return {
      passed: parsed.passed,
      failed: parsed.failed,
      output: stdout.slice(-2000),
      errors: parsed.errors,
    };
  } catch (error) {
    const output = error instanceof Error ? error.message : String(error);
    return { passed: 0, failed: 1, output: output.slice(-2000), errors: [output.slice(-1000)] };
  } finally {
    try { fss.unlinkSync(file); } catch {}
  }
}

/** ── Main ── */

async function runFamily(family: string, suiteFile: string) {
  const suite = JSON.parse(await fs.readFile(path.join(FIXTURE, suiteFile), "utf8")) as any;
  const cases = suite.cases as any[];
  const outFile = path.join(OUTPUT, `${family}-subjects.json`);

  // Load checkpoint
  let data: SuiteSubjects = {
    family,
    suiteId: suite.suite_id,
    cases: [],
    generatedAt: new Date().toISOString(),
  };
  try {
    data = JSON.parse(await fs.readFile(outFile, "utf8"));
    if (data.family !== family) throw new Error("mismatch");
  } catch {}

  const completed = new Set(data.cases.map((c) => c.caseId));

  for (const caseItem of cases) {
    if (completed.has(caseItem.case_id)) continue;

    console.log(`  [${family}] running ${caseItem.case_id}...`);

    const subjects: SubjectRun[] = [];
    for (const model of SUBJECT_MODELS) {
      if (model.id === "chatgpt/gpt-5.4") {
        console.log(`    waiting 15s before ${model.label}...`);
        await sleep(15_000);
      }

      const response = await callModel(caseItem.messages, model.id);
      const run: SubjectRun = {
        modelId: model.id,
        modelLabel: model.label,
        actualText: response.text,
        latencyMs: response.latencyMs,
        promptTokens: response.promptTokens,
        completionTokens: response.completionTokens,
        totalTokens: response.totalTokens,
      };

      if (family === "mmlu_pro") {
        const answer = extractMmluAnswer(response.text);
        run.extractedAnswer = answer;
        run.binaryCorrect = answer === caseItem.expected_response?.trim().toUpperCase();
      }

      if (family === "bigcodebench") {
        const code = extractPython(response.text);
        run.extractedCode = code;
        if (code && caseItem.test_code && caseItem.entry_point) {
          console.log(`    running official tests for ${model.label}...`);
          run.exec = runBigCodeTests(code, caseItem.test_code, caseItem.entry_point, caseItem.case_id, model.label);
          console.log(`    -> passed=${run.exec.passed} failed=${run.exec.failed}`);
        } else {
          run.exec = { passed: 0, failed: 1, output: "", errors: ["Code extraction failed"] };
        }
      }

      subjects.push(run);
      console.log(
        `    ${model.label}: ${response.latencyMs}ms, ${response.completionTokens}ctokens, text_len=${response.text.length}`,
      );
    }

    data.cases.push({ caseId: caseItem.case_id, subjects });
    data.generatedAt = new Date().toISOString();

    // Write checkpoint after every case
    await fs.writeFile(outFile, JSON.stringify(data, null, 2), "utf8");
  }

  console.log(`  [${family}] done: ${data.cases.length}/${cases.length} cases`);
}

async function main() {
  await fs.mkdir(OUTPUT, { recursive: true });

  console.log("=== PHASE 1: Run all subjects (no judging) ===\n");

  for (const [family, file] of Object.entries({
    mmlu_pro: "mmlu-pro-v1.json",
    bigcodebench: "bigcodebench-v1.json",
    arena_hard_200: "arena-hard-v1.json",
  })) {
    console.log(`\n-- ${family} --`);
    await runFamily(family, file);
  }

  console.log("\nAll subjects completed. Subjects files in output/");
}

main().catch((error) => {
  console.error(error instanceof Error ? error.stack : String(error));
  process.exit(1);
});
