    ? `official_test_result: passed=${modelA.exec.passed} failed=${modelA.exec.failed} errors=${modelA.exec.errors.slice(0, 3).join("; ")}`
    : "";

  const modelBExec = modelB.exec
    ? `official_test_result: passed=${modelB.exec.passed} failed=${modelB.exec.failed} errors=${modelB.exec.errors.slice(0, 3).join("; ")}`
    : "";

  const questionText =
    caseItem.messages?.map((m: any) => `${m.role.toUpperCase()}: ${m.content}`).join("\n\n") ?? "";

  const prompt = [
    "You are grading two benchmark responses side by side.",
    "Use the benchmark question, expected answer, grading criteria, and official test results.",
    "Score each response from 0.0 to 1.0, pick winner, explain concretely.",
    "",
    'Output ONLY one JSON object on one line: {"winner":"model_a|model_b|tie","model_a_score":0.0,"model_b_score":0.0,"rationale":"..."}',
    "",
    "Rules:",
    "- For MMLU-Pro: the expected answer is authoritative. One correct letter = 1.0, anything else = 0.0.",
    "- For BigCodeBench: official test results are the primary signal. If both pass, tie.",
    "- For Arena-Hard: evaluate quality against the prompt criteria.",
    "- Do not reward verbosity.",
    "- If both materially equivalent, return tie.",
    "",
    "## QUESTION",
    questionText,
    "",
    "## EXPECTED ANSWER",
    caseItem.expected_response ?? "N/A",
    "",
    "## GRADING CRITERIA",
    caseItem.grading_criteria ?? "See prompt",
    "",
    "## MODEL A",
    `model_id: ${modelA.modelId}`,
    `raw_output:\n${modelAText}`,
    modelA.extractedAnswer ? `parsed_answer: ${modelA.extractedAnswer}` : "",
    modelAExec,
    "",
    "## MODEL B",
    `model_id: ${modelB.modelId}`,
    `raw_output:\n${modelBText}`,
    modelB.extractedAnswer ? `parsed_answer: ${modelB.extractedAnswer}` : "",
    modelBExec,
  ]
    .filter(Boolean)
    .join("\n");

  try {
    const judged = await callModel([{ role: "user", content: prompt }], JUDGE_MODEL);
    const parsed = tryParseJson(judged.text);
    if (!parsed) {
      // Fallback: try to extract JSON from the text
      const jsonMatch = judged.text.match(/\{[\s\S]*"winner"[\s\S]*\}/);
      if (jsonMatch) {
        const fallback = tryParseJson(jsonMatch[0]);
        if (fallback) {
          return {
            winner: fallback.winner as any,
            model_a_score: Number(fallback.model_a_score ?? 0),
            model_b_score: Number(fallback.model_b_score ?? 0),
            rationale: String(fallback.rationale ?? "judge fallback parse"),
          };
        }
      }
      throw new Error(`Judge returned non-JSON: ${judged.text.slice(0, 400)}`);
    }
    const winner = parsed.winner;
    if (winner !== "model_a" && winner !== "model_b" && winner !== "tie") {
      throw new Error(`Invalid judge winner: ${String(winner)}`);
    }
    return {
      winner,
      model_a_score: Number(parsed.model_a_score ?? 0),
      model_b_score: Number(parsed.model_b_score ?? 0),
      rationale: String(parsed.rationale ?? ""),
    };
  } catch (error) {
    console.error(`    judge error for ${caseItem.case_id}: ${error instanceof Error ? error.message : String(error)}`);
    // Return failed judge result
    return {
      winner: "tie",
      model_a_score: 0,
      model_b_score: 0,
      rationale: `Judge failed: ${error instanceof Error ? error.message : String(error)}`,
    };
  }
}

function summarizeFamily(artifacts: CaseArtifact[]) {
  const aWins = artifacts.filter((x) => x.judge.winner === "model_a").length;
  const bWins = artifacts.filter((x) => x.judge.winner === "model_b").length;
  const ties = artifacts.filter((x) => x.judge.winner === "tie").length;
  const aAvg =
    artifacts.length > 0
      ? artifacts.reduce((s, x) => s + x.judge.model_a_score, 0) / artifacts.length
      : 0;
  const bAvg =
    artifacts.length > 0
      ? artifacts.reduce((s, x) => s + x.judge.model_b_score, 0) / artifacts.length
      : 0;
  const mmluA = artifacts.filter((x) => x.modelA.binaryCorrect).length;
  const mmluB = artifacts.filter((x) => x.modelB.binaryCorrect).length;
  return { aWins, bWins, ties, aAvg, bAvg, mmluA, mmluB };
}

async function judgeFamily(family: string, suiteFile: string) {
  const suite = JSON.parse(await fs.readFile(path.join(FIXTURE, suiteFile), "utf8")) as any;
  const subjectsFile = path.join(OUTPUT, `${family}-subjects.json`);
  const outFile = path.join(OUTPUT, `${family}-judged.json`);

  // Load Phase 1 subjects
  let subjectsData: SuiteSubjects;
  try {
    subjectsData = JSON.parse(await fs.readFile(subjectsFile, "utf8"));
  } catch {
    console.error(`  ERROR: ${subjectsFile} not found. Run Phase 1 first.`);
    return;
  }

  if (subjectsData.cases.length === 0) {
    console.log(`  No subject data for ${family}, skipping.`);
    return;
  }

  // Load checkpoint
  let artifacts: CaseArtifact[] = [];
  try {
    const prior = JSON.parse(await fs.readFile(outFile, "utf8"));
    artifacts = prior.artifacts ?? [];
  } catch {}

  const completed = new Set(artifacts.map((a) => a.caseId));
  const caseMap = new Map(suite.cases.map((c: any) => [c.case_id, c]));

  for (const { caseId, subjects } of subjectsData.cases) {
    if (completed.has(caseId)) continue;
    if (subjects.length < 2) {
      console.log(`  skipping ${caseId}: need 2 subjects, got ${subjects.length}`);
      continue;
    }

    const caseItem = caseMap.get(caseId);
    if (!caseItem) {
      console.log(`  skipping ${caseId}: not found in suite`);
      continue;
    }

    const modelA = subjects[0];
    const modelB = subjects[1];

    console.log(`  judging ${caseId} (${modelA.modelLabel} vs ${modelB.modelLabel})...`);

    const judge = await judgePairwise(caseItem, modelA, modelB);
    console.log(`    -> winner=${judge.winner} a=${judge.model_a_score.toFixed(2)} b=${judge.model_b_score.toFixed(2)}`);

    artifacts.push({
      family,
      suiteId: suite.suite_id,
      caseId,
      category: caseItem.category ?? "",
      difficulty: caseItem.difficulty_bucket ?? "medium",
      question: caseItem.messages?.map((m: any) => `${m.role}: ${m.content}`).join("\n\n") ?? "",
      expectedResponse: caseItem.expected_response ?? "",
      gradingCriteria: caseItem.grading_criteria ?? "",
      taxonomy: {
        roleId: caseItem.taxonomy_tags?.roleId ?? "",
        taskType: caseItem.taxonomy_tags?.taskType ?? "",
        domain: caseItem.taxonomy_tags?.domain ?? "",
      },
      modelA,
      modelB,
      judge,
    });

    // Write checkpoint after each case
    const summary = summarizeFamily(artifacts);
    await fs.writeFile(
      outFile,
      JSON.stringify(
        {
          family,
          suiteId: suite.suite_id,
          judgeModel: JUDGE_MODEL,
          artifacts,
          summary,
        },
        null,
        2,
      ) + "\n",
      "utf8",
    );

    // Rate limit judge calls
    await sleep(15_000);
  }

  const summary = summarizeFamily(artifacts);
  console.log(
    `  [${family}] done: aWins=${summary.aWins} bWins=${summary.bWins} ties=${summary.ties} aAvg=${summary.aAvg.toFixed(2)} bAvg=${summary.bAvg.toFixed(2)}`,
  );

  return { family, suiteId: suite.suite_id, cases: artifacts.length, judgeModel: JUDGE_MODEL, ...summary };
}

async function main() {
  await fs.mkdir(OUTPUT, { recursive: true });

