/**
 * Phase 1: Run all subjects through all benchmarks.
 * Saves raw responses to {family}-subjects.json checkpoint files.
 * Judging is done separately in run-phase2-judge.js.
 */
import * as fs from "node:fs/promises";
import * as fss from "node:fs";
import * as path from "node:path";
import { execFileSync } from "node:child_process";

const ROOT = "C:\\Users\\erikb\\AppData\\Local\\Temp\\rm-pilot-spike";
const FIXTURE = path.join(ROOT, "fixture");
const OUTPUT = path.join(ROOT, "output");
const ENDPOINT = "http://127.0.0.1:3456/v1/chat/completions";
const PYTHON = "C:\\Python314\\python.exe";

const SUBJECT_MODELS = [
  { id: "difficulty.remote-only", label: "deepseek_v4_pro" },
  { id: "chatgpt/gpt-5.4", label: "gpt_5_4" },
] as const;

const TRANSIENT_RETRY_DELAYS_MS = [15_000, 45_000, 90_000, 180_000];

/** ── Types ── */

interface ModelCallResult {
  text: string;
  latencyMs: number;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  modelUsed: string;
}

interface ExecResult {
  passed: number;
  failed: number;
  output: string;
  errors: string[];
}

interface SubjectRun {
  modelId: string;
  modelLabel: string;
  actualText: string;
  extractedAnswer?: string;
  extractedCode?: string;
  latencyMs: number;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  exec?: ExecResult;
  binaryCorrect?: boolean;
}

interface CaseSubjects {
  caseId: string;
  subjects: SubjectRun[];
}

interface SuiteSubjects {
  family: string;
  suiteId: string;
  cases: CaseSubjects[];
  generatedAt: string;
}

/** ── Helpers ── */

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function extractFence(raw: string, lang?: string): string | null {
  const regex = /```([a-zA-Z0-9_-]*)\r?\n([\s\S]*?)```/g;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(raw)) !== null) {
    const actualLang = (match[1] ?? "").toLowerCase();
    if (!lang || !actualLang || actualLang === lang.toLowerCase()) {
      return match[2].trim();
    }
  }
  return null;
}

function tryParseJson(raw: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(raw.trim());
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed as Record<string, unknown>;
  } catch {}
  const fenced = extractFence(raw, "json");
  if (!fenced) return null;
  try {
    const parsed = JSON.parse(fenced);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed as Record<string, unknown>;
  } catch {}
  return null;
}

function extractMmluAnswer(raw: string): string {
  const json = tryParseJson(raw);
  const fromJson = typeof json?.answer === "string" ? json.answer : "";
  const text = (fromJson || raw).trim().toUpperCase();
  const match = text.match(/\b([A-J])\b/);
  return match?.[1] ?? "";
}

function extractPython(raw: string): string {
  return extractFence(raw, "python") ?? extractFence(raw) ?? "";
}

async function callModel(
  messages: readonly { role: string; content: string }[],
  model: string,
): Promise<ModelCallResult> {
  for (let attempt = 0; attempt <= TRANSIENT_RETRY_DELAYS_MS.length; attempt += 1) {
    try {
      const started = Date.now();
      const res = await fetch(ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model, messages, temperature: 0 }),
        signal: AbortSignal.timeout(300_000),
      });
      if (res.ok) {
        const json = (await res.json()) as {
          model?: string;
          choices?: Array<{ message?: { content?: string } }>;
          usage?: { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number };
        };
        return {
          text: json.choices?.[0]?.message?.content ?? "",
          latencyMs: Date.now() - started,
          promptTokens: json.usage?.prompt_tokens ?? 0,
          completionTokens: json.usage?.completion_tokens ?? 0,
          totalTokens: json.usage?.total_tokens ?? 0,
          modelUsed: json.model ?? model,
        };
      }
      const text = await res.text().catch(() => "unknown");
      const err = new Error(`HTTP ${res.status}: ${text.slice(0, 400)}`);
      const transient =
        res.status === 503 &&
        /temporarily unavailable|recent execution failures|no_eligible_target/i.test(text);
      if (!transient || attempt === TRANSIENT_RETRY_DELAYS_MS.length) throw err;
    } catch (error) {
      const lastError = error instanceof Error ? error : new Error(String(error));
      if (attempt === TRANSIENT_RETRY_DELAYS_MS.length) throw lastError;
    }
    await sleep(TRANSIENT_RETRY_DELAYS_MS[attempt]);
  }
  throw new Error("unreachable");
}

function sanitizePython(code: string): string {
  return code.replace(/^\s*```python\s*/i, "").replace(/\s*```\s*$/i, "").trim();
}

function runBigCodeTests(
  code: string,
  testCode: string,
  entryPoint: string,
