  const slug = `${caseId}-${modelLabel}-${Date.now()}`.replace(/[^a-zA-Z0-9_-]/g, "_");
  const file = path.join(tmpDir, `${slug}.py`);
  const harness = [
    sanitizePython(code),
    "",
    testCode,
    "",
    "if __name__ == '__main__':",
    "    import json",
    "    import unittest",
    "    suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestCases)",
    "    result = unittest.TextTestRunner(verbosity=0).run(suite)",
    "    payload = {",
    "        'passed': result.testsRun - len(result.failures) - len(result.errors),",
    "        'failed': len(result.failures) + len(result.errors),",
    "        'errors': [str(x[1])[:500] for x in result.failures + result.errors],",
