      if (family === "mmlu_pro") {
        const answer = extractMmluAnswer(response.text);
        run.extractedAnswer = answer;
        run.binaryCorrect = answer === caseItem.expected_response?.trim().toUpperCase();
      }

      if (family === "bigcodebench") {
        const code = extractPython(response.text);
        run.extractedCode = code;
        if (code && caseItem.test_code && caseItem.entry_point) {
