          run.exec = runBigCodeTests(code, caseItem.test_code, caseItem.entry_point, caseItem.case_id, model.label);
          console.log(`    -> passed=${run.exec.passed} failed=${run.exec.failed}`);
        } else {
          run.exec = { passed: 0, failed: 1, output: "", errors: ["Code extraction failed"] };
        }
      }

      subjects.push(run);
      console.log(
        `    ${model.label}: ${response.latencyMs}ms, ${response.completionTokens}ctokens, text_len=${response.text.length}`,
