    data.cases.push({ caseId: caseItem.case_id, subjects });
    data.generatedAt = new Date().toISOString();

    // Write checkpoint after every case
    await fs.writeFile(outFile, JSON.stringify(data, null, 2), "utf8");
  }

  console.log(`  [${family}] done: ${data.cases.length}/${cases.length} cases`);
